 const ignore=$('tpfInlineIgnore');ignore.classList.toggle('hidden',correctionReturn!=='whatsapp');ignore.onclick=()=>{ignoreName(correctionChat,correctionWhatsapp,true);back.classList.add('hidden');refreshWhatsapp()};
